def anti_shuffle(s):
    words = s.split()
    sorted_words = []
    for word in words:
        sorted_word = ''.join(sorted(word, key=lambda x: x if x.isalnum() else '')) + word[len(word) - word[::-1].find(word[len(word) - 1])] if word[len(word) - 1].isalnum() else ''.join(sorted(word, key=lambda x: x if x.isalnum() else ''))
        sorted_words.append(sorted_word)
    return ' '.join(sorted_words)

